// ============================================================================
//  POOL COMPLETO DE POKEMON - RANDOM TRAINER MONS (CFRU-expansion)
// ----------------------------------------------------------------------------
//  Usado por FLAG_RANDOM_TRAINER_POOL (include/constants/flags.h, = 0x28E) e por
//  FLAG_RANDOM_GIVEMON_POOL (= 0x28F).
//  Quando FLAG_RANDOM_TRAINER_POOL esta ativa, CreateNPCTrainerParty (build_pokemon.c)
//  sorteia uma entrada aleatoria deste array para CADA pokemon de CADA treinador NPC,
//  substituindo especie, moves, item e nature originais do treinador.
//  Quando FLAG_RANDOM_GIVEMON_POOL esta ativa, ScriptGiveMon (build_pokemon.c) sorteia
//  uma entrada deste mesmo array no lugar do Pokemon que o script "givepokemon" ia dar.
//  Independentes entre si e de FLAG_RANDOM_TRAINER_TEAM (que usa outro arquivo/array,
//  src/Tables/random_trainer_pool.h / gRandomTrainerSpeciesPool, e so troca a especie).
//
//  Regras seguidas ao montar esta lista:
//   - Apenas pokemon de ultimo estagio de evolucao OU estagio unico.
//   - Moveset estilo competitivo (Smogon).
//   - Item nunca e' Choice Band / Choice Scarf / Choice Specs.
//   - Pokemon com Mega Evolucao (classica ou de Legends Z-A) segura a
//     propria Mega Stone (isMegaCapable = 1).
//
//  Total: 519 entradas (88 delas mega-capazes).
//
//  Para adicionar/remover pokemon, edite direto este arquivo no formato:
//    { SPECIES_X, {MOVE_A, MOVE_B, MOVE_C, MOVE_D}, ITEM_Y, NATURE_Z, isMega },
// ============================================================================

struct RandomTrainerPoolMon
{
	u16 species;
	u16 moves[4];
	u16 item;
	u8 nature;
	bool8 isMegaCapable;
};

